import{_ as t,o as _,c as a,a4 as s}from"./chunks/framework.hWlsC8BY.js";const f=JSON.parse('{"title":"农业农村部、市场监管总局、国家知识产权局联合实施农业品牌保护专项行动2026-09-18","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"农业农村部、市场监管总局、国家知识产权局联合实施农业品牌保护专项行动2026-09-18","date":"2026-09-18T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202609/t20260918_6487842.htm","summary":"本网讯\\n近日，农业农村部、市场监管总局和国家知识产权局联合印发《农业品牌保护专项行动实施方案（2026—2027年）》（以下简称《方案》），提出带动一批特色品牌、壮大一批品牌主体，集中力量查办一批侵权违法案件、震慑一批侵权行为，完善部门协同保护机制，健全覆盖农业品牌培育、管理、使用、推广的全链条保护体系，增强消费信心、提升品牌价值。\\n本次专项行动围绕四大重点任务展开。...\\n","contentHash":"f176c62c4d4591571a41872841c33350","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-09-18-农业农村部-市场监管总局-国家知识产权局联合实施农业品牌保护专项行动.md","filePath":"policies/2026-09-18-农业农村部-市场监管总局-国家知识产权局联合实施农业品牌保护专项行动.md"}'),r={name:"policies/2026-09-18-农业农村部-市场监管总局-国家知识产权局联合实施农业品牌保护专项行动.md"};function o(n,e,c,l,p,i){return _(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="农业农村部、市场监管总局、国家知识产权局联合实施农业品牌保护专项行动2026-09-18" tabindex="-1">农业农村部、市场监管总局、国家知识产权局联合实施农业品牌保护专项行动2026-09-18 <a class="header-anchor" href="#农业农村部、市场监管总局、国家知识产权局联合实施农业品牌保护专项行动2026-09-18" aria-label="Permalink to &quot;农业农村部、市场监管总局、国家知识产权局联合实施农业品牌保护专项行动2026-09-18&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202609/t20260918_6487842.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-09-18 摘要: 本网讯 近日，农业农村部、市场监管总局和国家知识产权局联合印发《农业品牌保护专项行动实施方案（2026—2027年）》（以下简称《方案》），提出带动一批特色品牌、壮大一批品牌主体，集中力量查办一批侵权违法案件、震慑一批侵权行为，完善部门协同保护机制，健全覆盖农业品牌培育、管理、使用、推广的全链条保护体系，增强消费信心、提升品牌价值。 本次专项行动围绕四大重点任务展开。...</p></blockquote><p>本次专项行动围绕四大重点任务展开。在品牌农产品质量安全监管执法方面，全面落实承诺达标合格证制度，健全问题通报和协查机制，强化产地准出分类监管。在涉农商标、专利领域违法行为方面，严厉查处涉农商标侵权、地理标志侵权、假冒专利等违法行为，强化对农产品网络销售、直播带货中侵权假冒行为的查处力度，严厉打击恶意抢注或侵犯老字号商标、驰名商标的行为。在打击不正当竞争行为方面，要求重点查处擅自使用知名区域公用品牌、地理标志品牌等特有的和近似的名称、包装、装潢等混淆行为，重点查处经营者对其商品性能、功能、质量、销售状况、用户评价、曾获荣誉等作虚假或者引人误解的商业宣传，以及通过商业诋毁等方式损害竞争对手的行为。在涉农知识产权行政保护方面，支持农业品牌主体通过商标、专利、地理标志、植物新品种等多维度知识产权布局，强化品牌权益保护。推动知识产权公共服务机构聚焦重点农业产业，提供维权咨询、侵权判定、纠纷调解等专业化公益服务，提升农业品牌主体知识产权管理能力。</p><p>在工作措施上，《方案》提出加强部门协作配合，各级农业农村部门、市场监管部门、知识产权管理部门建立常态化沟通协调机制，明确职责分工，加强信息共享，开展联合执法行动，对涉及地域广、社会关注度高、案情复杂的大要案件挂牌督办。针对农业品牌网络侵权行为隐蔽性强、维权取证难度大等突出问题，指导网络平台建立快速响应合作机制，畅通品牌授权核验、侵权线索通报、电子证据固定等渠道。《方案》强调完善品牌管理制度，推动条件成熟的地区加快农业品牌保护地方性立法进度，建立健全农业品牌目录制度，完善品牌认定、动态管理和退出机制。实施农业品牌主体能力提升计划，鼓励各级商标品牌指导站开展专项服务指导，增强品牌管理、风险防控和主动维权能力。</p><p>专项行动自《方案》印发之日起至2027年12月31日开展，分动员部署、组织实施、总结提升三个阶段推进。</p><p><a href="https://scs.moa.gov.cn/gzdt/202609/t20260918_6487842.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',6)])])}const m=t(r,[["render",o]]);export{f as __pageData,m as default};
